/**
 * Maps cropCode or cropName to a plant icon image path under /assets/images/plant-icons/.
 * Falls back to lua.png for any unmapped crop.
 */

const FALLBACK = "/assets/images/plant-icons/lua.png";

export function normalizeCropText(str?: string | null): string {
  if (!str) return "";
  return str
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/Đ/g, "D")
    .replace(/[^A-Z0-9]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");
}

