export function getCropImagePath(cropCode?: string | null, cropName?: string | null): string {
  const rawCode = (cropCode || "").trim();
  const rawName = (cropName || "").trim();

  // 1. Direct exact match by raw cropCode
  if (rawCode && CROP_ICON_MAP[rawCode]) return CROP_ICON_MAP[rawCode];

  const normCode = normalizeCropText(rawCode);
  const normName = normalizeCropText(rawName);

  // 2. Exact match on normalized code or name
  if (normCode && CROP_ICON_MAP[normCode]) return CROP_ICON_MAP[normCode];
  if (normName && CROP_ICON_MAP[normName]) return CROP_ICON_MAP[normName];

  // 3. Keyword matching
  const combined = `${normCode}_${normName}`;

  // Priority: Xà lách/Salad, Bắp (không phải bắp cải), Cà chua -> default cây lúa (FALLBACK)
  if (
    combined.includes("XA_LACH") ||
    combined.includes("SA_LACH") ||
    combined.includes("SALAD") ||
    combined.includes("LETTUCE") ||
    combined.includes("CA_CHUA") ||
    combined.includes("TOMATO") ||
    ((combined.includes("BAP") || combined.includes("NGO") || combined.includes("CORN")) && !combined.includes("BAP_CAI"))
  ) {
    return FALLBACK;
  }

  // Bắp cải -> bap-cai.png
  if (combined.includes("BAP_CAI") || combined.includes("CABBAGE")) {
    return "/assets/images/plant-icons/bap-cai.png";
  }

  // Đậu / Đậu phộng / Đậu phông -> dau.png
  if (
    combined.includes("DAU_PHONG") ||
    combined.includes("AU_PHONG") ||
    combined.includes("PEANUT") ||
    combined.includes("LAC") ||
    (combined.includes("DAU") && !combined.includes("DAU_TAY") && !combined.includes("DAU_HAU"))
  ) {
    return "/assets/images/plant-icons/dau.png";
  }

  // Cải xanh -> rau-an-la.png
  if (combined.includes("CAI_XANH")) {
    return "/assets/images/plant-icons/rau-an-la.png";
  }

  // Nhãn -> nhan.png
  if (combined.includes("NHAN") || combined.includes("LONGAN")) {
    return "/assets/images/plant-icons/nhan.png";
  }

  // Tiêu / Hồ tiêu -> ho-tieu.png
  if (combined.includes("TIEU") || combined.includes("HO_TIEU") || combined.includes("PEPPER")) {
    return "/assets/images/plant-icons/ho-tieu.png";
  }

  if (combined.includes("NHO") || combined.includes("GRAPE")) {
    return "/assets/images/plant-icons/nho.png";
  }

  if (combined.includes("QUYT") || combined.includes("MANDARIN")) {
    return "/assets/images/plant-icons/quyt.png";
  }

  if (combined.includes("LE") || combined.includes("PEAR")) {
    return "/assets/images/plant-icons/le.png";
  }

  // 4. Fuzzy fallback search in map
  for (const [key, path] of Object.entries(CROP_ICON_MAP)) {
    if (
      (normCode && (normCode.includes(key) || key.includes(normCode))) ||
      (normName && (normName.includes(key) || key.includes(normName)))
    ) {
      return path;
    }
  }

  return FALLBACK;
}
